Adaptation_method:
If you need to cache error results for specific use cases, you must implement custom caching. For example:

Before:
// Errors automatically cached
const memoizedFn = async.memoize(originalFn);
memoizedFn('arg', callback); // both error and result cached per arguments

After:
// Implement custom error caching if needed
const cache = new Map();
const memoizedFn = async.memoize((arg, cb) => {
  if (cache.has(arg)) {
    cb(...cache.get(arg));
    return;
  }
  originalFn(arg, (err, result) => {
    if (err) {
      cache.set(arg, [err, result]);
    }
    cb(err, result);
  });
});
